package org.telegram.messenger;import java.util.*;import org.telegram.tgnet.TLRPC;import androidx.collection.LongSparseArray;public final class MessagesController {public final Map<Long,TLRPC.User> users=new HashMap<>();public final Map<Long,TLRPC.Chat> chats=new HashMap<>();public final LongSparseArray<TLRPC.Dialog> dialogs_dict=new LongSparseArray<>();static final MessagesController[] a=new MessagesController[4];static{for(int i=0;i<4;i++)a[i]=new MessagesController();}public static MessagesController getInstance(int i){return a[i];}public TLRPC.User getUser(Long id){return users.get(id);}public TLRPC.Chat getChat(Long id){return chats.get(id);}}
